import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const cart = JSON.parse(sessionStorage.getItem("cart")) || [];
    setCartItems(cart);
  }, []);

  const removeItem = (id) => {
    const updated = cartItems.filter((item) => item.listing_id !== id);
    setCartItems(updated);
    sessionStorage.setItem("cart", JSON.stringify(updated));
  };

  const subtotal = cartItems.reduce((sum, item) => sum + parseFloat(item.price), 0);
  const tax = subtotal * 0.08;
  const shipping = Math.floor(Math.random() * 5) + 3;
  const total = (subtotal + tax + shipping).toFixed(2);

  return (
    <div className="page-container">
      <Navbar />
      <div className="main-content cart-page">
        <h2>Your Cart</h2>
        {cartItems.length === 0 ? (
          <p>Your cart is empty.</p>
        ) : (
          <>
            {cartItems.map((item) => (
              <div key={item.listing_id} className="cart-item">
                <h3>{item.title}</h3>
                <p>Price: ${item.price}</p>
                <button onClick={() => removeItem(item.listing_id)} className="remove-btn">Remove</button>
              </div>
            ))}
            <div className="cart-summary">
              <p>Subtotal: ${subtotal.toFixed(2)}</p>
              <p>Tax: ${tax.toFixed(2)}</p>
              <p>Shipping: ${shipping}</p>
              <p className="total">Total: ${total}</p>
              <button onClick={() => navigate("/checkout")} className="checkout-btn">Proceed to Checkout</button>
            </div>
          </>
        )}
      </div>
      <Footer />
    </div>
  );
};

export default Cart;
